      variant: { primary: 'bg-cyan-500 text-slate-950 hover:bg-cyan-600', secondary: 'bg-slate-800 text-slate-100 hover:bg-slate-700', outline: 'border border-slate-700 hover:bg-slate-800', ghost: 'hover:bg-slate-800 text-slate-300', destructive: 'bg-rose-500 text-white hover:bg-rose-600' },
